package recurrence

import (
	"testing"
	"time"

	"github.com/enjoys-in/cal-dev/internal/ics"
)

// A weekly 09:00 New York series, written by a CalDAV client, then regenerated by the server
// (an RSVP, a local invitation or a JMAP edit does this) and read back the way another client
// or a later request would: the text is all that survives. Before TZID was written the
// regenerated text had a fixed UTC DTSTART, so the series drifted an hour at the DST change.
func TestRegeneratedZonedSeriesKeepsWallClockAcrossDST(t *testing.T) {
	loc, err := time.LoadLocation("America/New_York")
	if err != nil {
		t.Skip("tzdata not available")
	}
	const raw = "BEGIN:VCALENDAR\r\nVERSION:2.0\r\n" +
		"BEGIN:VEVENT\r\nUID:ny-1\r\nDTSTART;TZID=America/New_York:20270301T090000\r\nDTEND;TZID=America/New_York:20270301T100000\r\n" +
		"RRULE:FREQ=WEEKLY\r\nEXDATE;TZID=America/New_York:20270308T090000\r\nSUMMARY:Standup\r\nEND:VEVENT\r\n" +
		"BEGIN:VEVENT\r\nUID:ny-1\r\nRECURRENCE-ID;TZID=America/New_York:20270322T090000\r\n" +
		"DTSTART;TZID=America/New_York:20270322T110000\r\nDTEND;TZID=America/New_York:20270322T120000\r\nSUMMARY:Standup (moved)\r\nEND:VEVENT\r\n" +
		"END:VCALENDAR\r\n"

	rows, err := ics.ParseICSAll(raw, 1, 1, "cal")
	if err != nil {
		t.Fatal(err)
	}
	regenerated := ics.FinalizeResource(rows)[0].RawICS
	back, err := ics.ParseICSAll(regenerated, 1, 1, "cal")
	if err != nil {
		t.Fatal(err)
	}

	occ := Group(back)[0].Expand(utc(2027, 3, 1, 0, 0), utc(2027, 4, 6, 0, 0), 0)
	var got []string
	for _, o := range occ {
		got = append(got, o.Start.In(loc).Format("2006-01-02 15:04"))
	}
	// Mar 8 is excluded; Mar 22 is moved from 09:00 to 11:00. Mar 14 is the DST change, so
	// the UTC time of 09:00 shifts from 14:00Z to 13:00Z but the wall clock must not.
	want := []string{"2027-03-01 09:00", "2027-03-15 09:00", "2027-03-22 11:00", "2027-03-29 09:00", "2027-04-05 09:00"}
	if len(got) != len(want) {
		t.Fatalf("occurrences = %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("occurrences = %v, want %v", got, want)
		}
	}
	if !occ[1].Start.Equal(utc(2027, 3, 15, 13, 0)) {
		t.Fatalf("after the DST change 09:00 is 13:00Z, got %v", occ[1].Start.UTC())
	}
}
